// Original authored vector primitives. No dependencies or network.
export const C={ink:'#252a24',green:'#17633e',leaf:'#6eaa4d',light:'#9ec478',deep:'#365f38',gold:'#e6ac29',pale:'#f5d77d',soil:'#e4b36a',cream:'#fff4cb'};
export function path(d,fill='none',stroke=C.ink,w=3,extra=''){return `<path d="${d}" fill="${fill}" stroke="${stroke}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round" ${extra}/>`}
export function transform(x,y,scale,angle,body){return `<g transform="translate(${x} ${y}) rotate(${angle}) scale(${scale})">${body}</g>`}
export function rng(seed){return()=>{seed=(1664525*seed+1013904223)>>>0;return seed/4294967296}}
export function grain(clipId,bounds,seed=17,count=90,colors=['#eff2c7','#2b5935']){const r=rng(seed);let out='';const [x,y,w,h]=bounds;for(let i=0;i<count;i++){let a=x+r()*w,b=y+r()*h,l=1+r()*7;out+=path(`M${a.toFixed(1)} ${b.toFixed(1)} q${(l*.5).toFixed(1)} ${(-r()*1.5).toFixed(1)} ${l.toFixed(1)} ${(-l*.4).toFixed(1)}`,'none',colors[i%colors.length],(.5+r()*.9).toFixed(2),`opacity="${(.14+r()*.2).toFixed(2)}"`)}return `<g clip-path="url(#${clipId})">${out}</g>`}
export function leaf(x,y,scale=1,angle=0,tone=C.leaf,variant=0){const d=variant%2===0?'M0 0 C-17 -13 -37 -24 -52 -49 C-64 -69 -65 -88 -71 -106 C-44 -102 -12 -89 -2 -65 C6 -45 -1 -19 0 0 Z':'M0 0 C-12 -19 -33 -26 -41 -45 C-50 -64 -48 -83 -54 -101 C-28 -94 -6 -80 1 -60 C8 -39 0 -18 0 0 Z';return transform(x,y,scale,angle,path(d,tone,C.ink,2.6)+path('M-2 -5 Q-16 -53 -58 -92','none',C.deep,1.7)+path('M-14 -36 Q-30 -38 -40 -47 M-24 -55 L-26 -75 M-38 -72 L-50 -74','none',C.deep,1.05)+path('M-43 -84 l10 3 M-39 -73 l16 9 M-26 -54 l9 4','none','#ecedbe',1.1,'opacity=".5"'))}
export function grass(x,y,scale=1,angle=0){return transform(x,y,scale,angle,path('M-24 0 Q-33 -16 -43 -26 Q-24 -19 -13 -4 Q-24 -35 -20 -48 Q-7 -29 -5 -7 Q-3 -40 7 -51 Q13 -35 3 -5 Q22 -34 37 -37 Q32 -17 12 1 Z',C.leaf,'none',0)+path('M-9 -2 L-19 -27 M0 -3 L5 -33 M10 -2 L27 -25','none',C.green,1.7))}
export function drop(x,y,scale=1,angle=23){return transform(x,y,scale,angle,path('M0 -26 C-2 -12 -12 7 -9 16 C-7 23 3 24 7 16 C11 9 4 -8 0 -26 Z','#f2f6e9',C.green,2.3)+path('M-5 10 Q-6 16 -1 18','none',C.leaf,1.2))}
export function goldMark(x,y,scale=1,angle=0){return transform(x,y,scale,angle,path('M0 0 C10 -7 31 -8 39 -2 C30 4 9 5 0 0 Z',C.gold,'none',0))}
export function flourish(){return path('M297 179 C465 155 578 190 718 177 C814 167 885 164 983 177 C883 172 811 176 720 185 C569 198 454 166 297 184 Z',C.gold,'none',0)+goldMark(177,112,1,205)+goldMark(177,134,.83,178)+goldMark(1098,112,1,-27)+goldMark(1101,136,.83,-2)}
export function shrub(x,y,scale=1,flip=1){const d='M-126 0 C-125 -16 -116 -29 -104 -27 C-113 -46 -93 -63 -77 -46 C-79 -77 -51 -85 -38 -62 C-28 -84 -4 -76 -4 -51 C12 -71 35 -60 34 -38 C56 -57 81 -40 75 -21 C98 -35 119 -18 121 -1 Z';const body=path(d,C.leaf,C.ink,3)+path('M-114 -3 C-60 -6 -5 -12 54 -5','none',C.green,2)+path('M-63 -7 l-13 -24 m14 18 l7 -27 M-23 -10 l-12 -28 m10 17 l11 -20 M21 -9 l9 -18 M61 -6 l-5 -17','none',C.deep,1.5)+path('M-96 -32 q7 -13 15 -8 M-67 -58 q13 -9 18 3 M-22 -53 q10 -10 18 1 M46 -29 q11 -10 19 -2','none','#d4dfa3',2.4,'opacity=".65"');return transform(x,y,scale,0,`<g transform="scale(${flip} 1)">${body}</g>`)}
export function flower(x,y,scale=1,angle=0,golden=false){const petals='M-8 -10 C-30 -38 -11 -50 -1 -23 C4 -54 30 -39 13 -17 C44 -30 51 -3 23 2 C51 19 31 38 12 18 C15 48 -12 47 -12 21 C-37 41 -51 16 -25 4 C-56 -4 -41 -31 -18 -13 Z';return transform(x,y,scale,angle,path('M-1 5 Q-9 72 -4 145','none',C.ink,4)+path('M-2 15 Q-7 82 -4 145','none',C.leaf,2.3)+leaf(-6,101,.58,25,C.leaf)+leaf(-5,117,.54,111,C.light,1)+path(petals,golden?C.gold:'#fffef6',C.ink,2.9)+path('M-12 -2 Q-8 -14 7 -9 Q22 -5 17 5 Q13 14 -3 12 Q-18 10 -12 -2 Z',golden?C.green:C.gold,C.ink,2)+path('M-7 2 q5 -6 12 -2','none',golden?C.leaf:C.pale,2.3))}
export function stone(x,y,scale=1){return transform(x,y,scale,0,path('M-32 0 Q-35 -16 -18 -20 Q-6 -45 17 -27 Q33 -28 39 0 Z','#fffdf3',C.ink,3)+path('M-27 -4 Q-24 -15 -16 -15 M-11 -24 Q1 -33 13 -23','none','#bac1ad',1.7))}
export function footprint(x,y,scale=1,angle=0,flip=1){return transform(x,y,scale,angle,`<g transform="scale(${flip} 1)">`+path('M-10 15 C-17 4 -16 -5 -10 -15 C-3 -27 13 -28 19 -19 C25 -10 20 -2 12 9 C7 17 8 26 -3 30 C-14 33 -18 25 -10 15 Z',C.green,'none',0)+path('M15 -33 C15 -40 23 -41 25 -35 C27 -29 16 -26 15 -33 Z M5 -36 C4 -43 12 -45 14 -39 C16 -33 7 -31 5 -36 Z M-4 -35 C-8 -41 -2 -46 2 -41 C6 -37 -1 -31 -4 -35 Z M-11 -31 C-16 -36 -12 -42 -8 -39 C-3 -36 -7 -29 -11 -31 Z M-17 -25 C-22 -29 -19 -35 -15 -32 C-11 -28 -14 -23 -17 -25 Z',C.green,'none',0)+'</g>')}
export class Scene{constructor(id,title){this.id=id;this.title=title;this.defs=[];this.groups=[]}clip(id,d){this.defs.push(`<clipPath id="${id}">${path(d,'white','none',0)}</clipPath>`);return id}add(id,label,body){this.groups.push({id,label,body});return this}svg(){return `<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="720" viewBox="0 0 1280 720" role="img" aria-label="${this.title}"><defs>${this.defs.join('')}</defs><rect width="1280" height="720" fill="white"/>${this.groups.map(g=>`<g id="${g.id}" data-label="${g.label}">${g.body}</g>`).join('')}</svg>`}}
